import{z as p,x as m,o as n,c as E,q as o,j as i,D as r,d as l,s as t,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"PRAM 与前缀和","description":"","frontmatter":{"title":"PRAM 与前缀和","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pram-prefix-sum.md","filePath":"cs/pram-prefix-sum.md","lastUpdated":1791413859000}'),A={name:"cs/pram-prefix-sum.md"};function u(c,a,B,h,f,_){const s=m("Mermaid");return n(),E("div",null,[a[2]||(a[2]=o('<h1 id="pram-与前缀和" tabindex="-1">PRAM 与前缀和 <a class="header-anchor" href="#pram-与前缀和" aria-label="Permalink to &quot;PRAM 与前缀和&quot;">​</a></h1><div class="epigraph"><p>共享内存并行：前缀和 $n$ 个数用 $O(\\log n)$ 时间、$O(n)$ 工作，是扫描、紧凑、链表的公共子程序。</p><footer>—— 据 Ladner and Fischer, Parallel Prefix Computation, 1980；JáJá, An Introduction to Parallel Algorithms 整理</footer></div><p>上一课<a href="/cs/external-memory-model">外存 I/O</a>换的是存储层次这个成本维度；本课换并行度。PRAM 是最朴素的并行模型：多处理器同步地在共享 RAM 上执行指令。缺口是前缀（scan）\\(s_i=a_1+\\cdots+a_i\\)——串行一遍 \\(O(n)\\)，看似天生串行，实则树形两遍只要 \\(O(\\log n)\\) 步。本课不重写 I/O 排序；后课 work-span 才给并行成本记账，CREW/CRCW 变体点名即可。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>在数组上造一棵平衡二叉树：上升遍求每个内部结点的区间和，下降遍把父结点积攒的左侧和往下推加，两遍各 \\(O(\\log n)\\) 跨度、总工作 \\(O(n)\\)。链表没有下标，前缀要先指针跳跃（Wyllie 的路径倍增）或随机化重排成数组。<span class="marginnote">「指针跳跃」翻译成大白话：每个结点起初只知道「下一个是谁」，每过一轮就改指到「下一个的下一个」，邻居距离一轮翻倍——\\(n\\) 长的链只需 \\(\\log n\\) 轮就全体知道了链尾。这类「距离每轮翻倍」的套路统称路径倍增。</span>CRCW 允许同拍并发写时还能更快，但那是在用更强的模型换结果。</p><p>缺口是前缀这个原语本身，不是 GPU 编程课。</p><h3 id="不是-mapreduce-语义" tabindex="-1">不是 MapReduce 语义 <a class="header-anchor" href="#不是-mapreduce-语义" aria-label="Permalink to &quot;不是 MapReduce 语义&quot;">​</a></h3><p>PRAM 是同步共享内存，每步所有处理器齐步走；MapReduce 是另一套数据并行模型，靠无共享机器间的分布式洗牌。两者的成本记账不能混用。</p><p><span class="marginnote">Ladner–Fischer 1980。Blelloch scan。后课 work-span 把 PRAM 界翻译成 fork-join。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法就是数组上的树两遍：上升、下降。有了 scan，一大批看似串行的应用立刻并行化——过滤（按谓词得 0/1 再排他 scan 算新下标，即紧凑）、并行词法分析、括号匹配——点名即可。</p>',11)),(n(),i(d,null,{default:r(()=>[t(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%95%B0%E7%BB%84%20a_i%22%5D%20--%3E%20UP%5B%22%E6%A0%91%E4%B8%8A%E8%A1%8C%E6%B1%82%E5%92%8C%22%5D%0A%20%20UP%20--%3E%20DN%5B%22%E4%B8%8B%E8%A1%8C%E6%8E%A8%E5%89%8D%E7%BC%80%22%5D%0A%20%20DN%20--%3E%20S%5B%22s_i%20%E5%89%8D%E7%BC%80%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"数字实例（排他 scan 怎么把「保留谁」变成「搬到哪」）：谓词得标志 \\([0,1,1,0]\\)（第 2、3 个元素要保留），对它做排他前缀和得 \\([0,0,1,2]\\)——每个要保留的元素正好拿到自己在输出数组里的新下标：原第 2 个去位置 \\(0\\)，第 3 个去位置 \\(1\\)。一次 scan 就完成了并行紧凑。")],-1)),a[4]||(a[4]=e("p",null,"树形两遍只用到结合律：\\(\\min\\)、\\(\\times\\) 等任何满足结合的运算都能代入，不必可交换。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"树形分解为什么对：结合律允许把区间任意切分再组合，内部结点的和与计算顺序无关。工作等于总运算次数，跨度等于依赖链的最长路径——上升、下降各贡献一段长 \\(\\log n\\) 的链。与快速幂同构：都是树形结合，快速幂用平方把指数对折，串行里一层一个平方；FFT 的蝶形网络同样是 \\(\\log n\\) 层的树形依赖。",-1)),a[7]||(a[7]=e("p",null,"用 \\(4\\) 个元素把两遍走一遍，树形结构一目了然（上行聚合，下行派发）：",-1)),(n(),i(d,null,{default:r(()=>[t(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22a1%3D3%22%5D%20--%3E%20U12%5B%224%22%5D%0A%20%20L2%5B%22a2%3D1%22%5D%20--%3E%20U12%0A%20%20L3%5B%22a3%3D4%22%5D%20--%3E%20U34%5B%225%22%5D%0A%20%20L4%5B%22a4%3D1%22%5D%20--%3E%20U34%0A%20%20U12%20--%3E%20R%5B%229%22%5D%0A%20%20U34%20--%3E%20R%0A%20%20R%20--%20%22%E4%B8%8B%E8%A1%8C%3A%20%E5%B7%A6%E8%BE%B9%E5%92%8C%200%22%20--%3E%20U12%0A%20%20R%20--%20%22%E4%B8%8B%E8%A1%8C%3A%20%E5%B7%A6%E8%BE%B9%E5%92%8C%204%22%20--%3E%20U34%0A%20%20U12%20--%20%220%20%2F%203%22%20--%3E%20L1%0A%20%20U12%20--%20%220%20%2F%203%22%20--%3E%20L2%0A%20%20U34%20--%20%224%20%2F%208%22%20--%3E%20L3%0A%20%20U34%20--%20%224%20%2F%208%22%20--%3E%20L4%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p><span class="marginnote">常见误区：初学者容易觉得前缀天生串行——「第 \\(i\\) 项要加完前 \\(i-1\\) 项才能算」。实际上结合律只要求「相邻段可以任意先合并再合并」，不要求按固定顺序：先把 \\(a_1+a_2\\)、\\(a_3+a_4\\) 同时算出，再合并，\\(s_4\\) 一样正确。看似串行的依赖其实是棵可以并行展开的树。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不追 EREW 下常数的最优实现，不写 MPI 这类网络模型。后课默认：前缀和 \\(O(\\log n)\\) 跨度、\\(O(n)\\) 工作。下一课 work-span 与 fork-join。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>前缀和是并行扫描原语。</li><li>\\(O(\\log n)\\) 时间、\\(O(n)\\) 工作。</li><li>结合律即可。</li><li>出处：Ladner and Fischer, 1980。</li></ul>',5))])}const C=p(A,[["render",u]]);export{D as __pageData,C as default};
